package ratelimiter

import (
	"fmt"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	capacity float64
	rate     float64 // tokens per second
	last     time.Time
	clock    Clock
}

// New creates a Limiter with the given capacity and refill rate.
// Both capacity and rate must be positive. A nil clock uses the system clock.
func New(capacity, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, fmt.Errorf("ratelimiter: capacity must be > 0, got %v", capacity)
	}
	if rate <= 0 {
		return nil, fmt.Errorf("ratelimiter: rate must be > 0, got %v", rate)
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		tokens:   capacity,
		capacity: capacity,
		rate:     rate,
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// AllowN reports whether n tokens are available. If so, it consumes them.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.last = now
	}

	if l.tokens >= float64(n) {
		l.tokens -= float64(n)
		return true
	}
	return false
}
